    from itertools import combinations_with_replacement
    return np.column_stack([a[:, i] * a[:, j] for (i, j) in combinations_with_replacement(range(a.shape[1]), 2)])

def cal(p):
    from scipy.optimize import least_squares
    (u, v) = (p['u'], p['v'])
    k = np.max(abs(u - v), 1) < 3
    (u, v) = (u[k], v[k])
    j = np.arange(4)
    opp = np.roll(j, 2)

    def db(a, i, q):
        return D(a[:, i], a[:, opp[i]], np.sin(q[0] * a[:, i]), np.sin(q[1] * a[:, opp[i]]))

    def err(q):
        return np.column_stack([db(u, i, q) @ ls(db(u, i, q), v[:, i]) - v[:, i] for i in j]).ravel()
    q = least_squares(err, [2.4, 2.4], bounds=(0.5, 5)).x
    c = np.stack([ls(db(u, i, q), v[:, i]) for i in j])
    print('A', q, np.std(err(q)), c)

    def inv(x):
        return np.stack([least_squares(lambda a: np.array([db(a[None], i, q)[0] @ c[i] for i in j]) - t, t, gtol=1e-12).x for t in x])
    return inv
